（行线接P1.0～P1.3，列线接P1.4～P1.7；有键返回0～15，无键返回0xFF）
#include <reg51.h>
#define uchar unsigned char
#define uint  unsigned int
void delayms(uint ms)          // 约1ms延时(12MHz)，参考实现
{
uint i, j;
for(i = ms; i > 0; i--)
for(j = 120; j > 0; j--);
}
uchar KeyScan4x4(void)
{
uchar row, col, temp;
P1 = 0xF0;                         // 行线全输出0，列线置1作输入
if((P1 & 0xF0) == 0xF0)
return 0xFF;                   // 无键按下
delayms(10);                       // 消抖
if((P1 & 0xF0) == 0xF0)
return 0xFF;
for(row = 0; row < 4; row++)       // 逐行扫描
{
P1 = ~(0x01 << row);           // 第row行输出0，其余为1
temp = P1 & 0xF0;              // 读列线
if(temp != 0xF0)               // 该行有键按下
{
for(col = 0; col < 4; col++)
{
if((temp & (0x10 << col)) == 0)
break;             // 找到为0的列
}
while((P1 & 0xF0) != 0xF0);// 等待释放
return row * 4 + col;      // 键值0~15
}
}
return 0xFF;
}
void main(void)
{
uchar key;
while(1)
{
key = KeyScan4x4();
if(key != 0xFF)
P2 = key;                  // 示例：键值送P2口
}
}

（12MHz；T0方式2每100μs中断一次，100次为一个PWM周期10ms；P3.2加速、P3.3减速，每次调10%；P1.0、P1.1接驱动芯片L298N的IN1、IN2）
#include <reg51.h>
#define uchar unsigned char
#define uint  unsigned int
sbit PWM_OUT = P1^0;           // 接电机驱动IN1
sbit MOTOR_B = P1^1;           // 接电机驱动IN2（置0，单向转）
sbit KEY_ADD = P3^2;           // 加速键
sbit KEY_SUB = P3^3;           // 减速键
uchar duty = 50;               // 占空比0~100(%)，初始50%
uchar cnt  = 0;                // PWM计数
void delayms(uint ms)          // 约1ms延时(12MHz)，参考实现
{
uint i, j;
for(i = ms; i > 0; i--)
for(j = 120; j > 0; j--);
}
void Timer0_Init(void)
{
TMOD &= 0xF0;
TMOD |= 0x02;              // T0方式2，自动重装
TH0 = 0x9C;                // 100us：256-100=156=9CH
TL0 = 0x9C;
ET0 = 1;
EA  = 1;
TR0 = 1;
}
void Timer0_ISR(void) interrupt 1  // 每100us进入一次
{
cnt++;
if(cnt >= 100)
cnt = 0;               // 100*100us=10ms为一个PWM周期
if(cnt < duty)
PWM_OUT = 1;           // 高电平时间=duty*100us
else
PWM_OUT = 0;
}
void main(void)
{
MOTOR_B = 0;
Timer0_Init();
while(1)
{
if(KEY_ADD == 0)                   // 加速
{
delayms(10);
if(KEY_ADD == 0)
{
if(duty < 100) duty += 10; // 占空比+10%
while(KEY_ADD == 0);       // 等待释放
}
}
if(KEY_SUB == 0)                   // 减速
{
delayms(10);
if(KEY_SUB == 0)
{
if(duty > 0) duty -= 10;   // 占空比-10%
while(KEY_SUB == 0);
}
}
}
}

（四相步进电机，经ULN2003驱动，A、B、C、D相接P1.0～P1.3；P3.2按键切换正反转，采用四相八拍）
#include <reg51.h>
#define uchar unsigned char
#define uint  unsigned int
sbit KEY_DIR = P3^2;           // 正反转切换键
// 四相八拍：A→AB→B→BC→C→CD→D→DA
uchar code STEP[8] = {0x01,0x03,0x02,0x06,0x04,0x0C,0x08,0x09};
void delayms(uint ms)          // 约1ms延时(12MHz)，参考实现
{
uint i, j;
for(i = ms; i > 0; i--)
for(j = 120; j > 0; j--);
}
void main(void)
{
uchar i = 0;
bit dir = 0;                       // 0正转，1反转
while(1)
{
if(KEY_DIR == 0)               // 检测方向键
{
delayms(10);
if(KEY_DIR == 0)
{
dir = !dir;            // 切换转向
while(KEY_DIR == 0);
}
}
P1 = (P1 & 0xF0) | STEP[i];    // 输出相序，不影响高4位
delayms(2);                    // 步进间隔，决定转速
if(dir == 0)
{
i++;                       // 正序通电→正转
if(i >= 8) i = 0;
}
else
{
if(i == 0) i = 8;          // 逆序通电→反转
i--;
}
}
}

（AT24C02器件地址A2A1A0=000，写地址0xA0，读地址0xA1；SDA接P2.0，SCL接P2.1）
#include <reg51.h>
#include <intrins.h>
#define uchar unsigned char
#define uint  unsigned int
sbit SDA = P2^0;
sbit SCL = P2^1;
void Delay5us(void)
{
_nop_(); _nop_(); _nop_(); _nop_(); _nop_();
}
void delayms(uint ms)          // 约1ms延时(12MHz)，参考实现
{
uint i, j;
for(i = ms; i > 0; i--)
for(j = 120; j > 0; j--);
}
void I2C_Start(void)           // 起始：SCL高时SDA高→低
{
SDA = 1; SCL = 1; Delay5us();
SDA = 0; Delay5us();
SCL = 0;
}
void I2C_Stop(void)            // 停止：SCL高时SDA低→高
{
SDA = 0; SCL = 1; Delay5us();
SDA = 1; Delay5us();
}
bit I2C_SendByte(uchar dat)    // 发送一字节，返回0表示收到ACK
{
uchar i;
bit ack;
for(i = 0; i < 8; i++)
{
SDA = (dat & 0x80) ? 1 : 0;    // 高位在前
dat <<= 1;
SCL = 1; Delay5us();
SCL = 0; Delay5us();
}
SDA = 1;                   // 释放SDA
SCL = 1; Delay5us();
ack = SDA;                 // 第9个时钟读应答
SCL = 0; Delay5us();
return ack;
}
uchar I2C_RecvByte(bit ack)    // 接收一字节，ack=0发ACK，ack=1发NACK
{
uchar i, dat = 0;
SDA = 1;                   // 释放SDA，准备读
for(i = 0; i < 8; i++)
{
SCL = 1; Delay5us();
dat <<= 1;
if(SDA) dat |= 0x01;
SCL = 0; Delay5us();
}
SDA = ack;                 // 第9个时钟发送应答
SCL = 1; Delay5us();
SCL = 0; SDA = 1;
return dat;
}
void AT24C02_Write(uchar addr, uchar dat)  // 字节写
{
I2C_Start();
I2C_SendByte(0xA0);        // 器件地址+写
I2C_SendByte(addr);        // 存储单元地址
I2C_SendByte(dat);         // 写入数据
I2C_Stop();
delayms(10);               // 等待片内写周期完成
}
uchar AT24C02_Read(uchar addr)             // 随机读
{
uchar dat;
I2C_Start();
I2C_SendByte(0xA0);        // 伪写：先写入单元地址
I2C_SendByte(addr);
I2C_Start();               // 重复起始
I2C_SendByte(0xA1);        // 器件地址+读
dat = I2C_RecvByte(1);     // 读一个字节后发NACK
I2C_Stop();
return dat;
}
void main(void)
{
AT24C02_Write(0x10, 0x55); // 向0x10单元写入0x55
P1 = AT24C02_Read(0x10);   // 读回送P1口（接LED验证）
while(1);
}

（软件模拟SPI主机，模式0，高位在前；CS接P1.0，SCK接P1.1，MOSI接P1.2，MISO接P1.3）
#include <reg51.h>
#define uchar unsigned char
#define uint  unsigned int
sbit SPI_CS   = P1^0;          // 片选，低有效
sbit SPI_SCK  = P1^1;          // 时钟
sbit SPI_MOSI = P1^2;          // 主出从入
sbit SPI_MISO = P1^3;          // 主入从出
void delayms(uint ms)          // 约1ms延时(12MHz)，参考实现
{
uint i, j;
for(i = ms; i > 0; i--)
for(j = 120; j > 0; j--);
}
uchar SPI_ReadWrite(uchar dat) // 全双工：发送一字节同时接收一字节
{
uchar i, rec = 0;
for(i = 0; i < 8; i++)
{
SPI_MOSI = (dat & 0x80) ? 1 : 0;   // SCK低时准备发送位
dat <<= 1;
SPI_SCK = 1;                       // 上升沿：双方采样
rec <<= 1;
if(SPI_MISO) rec |= 0x01;          // 读入从机数据位
SPI_SCK = 0;                       // 下降沿：双方移出下一位
}
return rec;
}
void main(void)
{
uchar r;
SPI_CS = 1;                // 初始不选中
SPI_SCK = 0;               // CPOL=0，空闲为低
SPI_MISO = 1;              // 作输入先写1
while(1)
{
SPI_CS = 0;            // 选中从器件
SPI_ReadWrite(0x03);   // 发送命令字（示例：读命令）
SPI_ReadWrite(0x00);   // 发送地址（示例）
r = SPI_ReadWrite(0xFF);   // 发送哑字节，同时读回数据
SPI_CS = 1;            // 结束本次通信
P2 = r;                // 读回数据送P2口显示
delayms(500);
}
}

（以ADC0809为例：D0～D7接P1，START与ALE相连接P3.0，OE接P3.1，EOC接P3.2，ADDA～ADDC接地选IN0，CLK由单片机ALE分频得约500kHz，Vref=5V；3位共阴极数码管动态显示0.00～5.00V，段码接P0（加上拉），位选P2.0～P2.2低电平选通）
