#define uchar unsigned char
#define uint  unsigned int
sbit ST  = P3^0;               // START和ALE（地址锁存）
sbit OE  = P3^1;               // 输出允许
sbit EOC = P3^2;               // 转换结束标志
uchar code SEG_CC[10] =        // 共阴极段码0~9
{0x3F,0x06,0x5B,0x4F,0x66,0x6D,0x7D,0x07,0x7F,0x6F};
void delayms(uint ms)          // 约1ms延时(12MHz)，参考实现
{
uint i, j;
for(i = ms; i > 0; i--)
for(j = 120; j > 0; j--);
}
uchar ADC0809_Read(void)       // 启动一次转换并读结果
{
uchar dat, i;
ST = 0;
ST = 1;                    // 上升沿：锁存通道地址并复位
ST = 0;                    // 下降沿：启动A/D转换
for(i = 0; i < 10; i++);   // 短延时，等待EOC变低
while(EOC == 0);           // 等待转换结束（EOC变高）
P1 = 0xFF;                 // P1作输入
OE = 1;                    // 打开输出三态门
dat = P1;                  // 读取转换结果
OE = 0;
return dat;
}
void Display(uint v)           // v为0~500，对应0.00~5.00V
{
P2 = 0xFF; P0 = SEG_CC[v / 100] | 0x80;   // 个位，带小数点
P2 = 0xFE; delayms(2);
P2 = 0xFF; P0 = SEG_CC[v / 10 % 10];      // 十分位
P2 = 0xFD; delayms(2);
P2 = 0xFF; P0 = SEG_CC[v % 10];           // 百分位
P2 = 0xFB; delayms(2);
P2 = 0xFF;                                // 消隐
}
void main(void)
{
uchar ad, k;
uint volt;
OE = 0; ST = 0;
while(1)
{
ad = ADC0809_Read();
volt = (unsigned long)ad * 500 / 255; // 换算为0.01V单位
for(k = 0; k < 30; k++)
Display(volt);                    // 动态扫描显示一段时间
}
}

